from climate_grid.trends import summarize
from climate_grid.attribution import multi_attribute

def det(mean, unc):
    return {"schema": "climate-grid/extremes-v1", "events": [
        {"start": "2000-01-01", "end": "2000-01-02", "days": 2,
         "cells": [[0, 0]], "peak": mean, "mean": mean, "uncertainty": unc}]}

periods = [
    {"year": y, "data": {"heat": det(m, 0.4)}}
    for y, m in [(2000, 10.0), (2001, 12.0), (2002, 14.0)]
]
trends = summarize(periods)
res = multi_attribute(trends, "heat", {"co2": [1.0, 2.0, 3.0], "sun": [3.0, 2.0, 1.0]})
assert res["years"] == [2000, 2001, 2002]
assert res["drivers"]["co2"] == {"slope": 2.0, "contribution": [-2.0, 0.0, 2.0]}
assert res["drivers"]["sun"] == {"slope": -2.0, "contribution": [-2.0, 0.0, 2.0]}
assert res["total"] == [-4.0, 0.0, 4.0]
print("end-to-end OK")
